// A simulated API call
function fetchUserData() {
  return new Promise(resolve => setTimeout(() => resolve({ name: "Alice" }), 500));
}

// The Async/Await way!
async function initApp() {
  try {
    console.log("1. Fetching...");

    // Code pauses here (for this function only) until the Promise resolves
    const data = await fetchUserData(); 

    console.log("2. Data received:", data.name);
  } catch (error) {
    // We can use standard try/catch blocks instead of .catch()!
    console.log("Error!", error);
  }
}

initApp();
console.log("This runs immediately, proving the thread isn't blocked!");
